// One feed per competitor from Google News (always) + their own blog RSS (if provided)
const cfg = $('Config').first().json;
const out = [];
for (const { json: c } of $input.all()) {
  if (!c.name) continue;
  if (String(c.active ?? 'TRUE').toUpperCase() === 'FALSE') continue;
  const query = c.news_query || `"${c.name}"`;
  const q = encodeURIComponent(`${query} when:${cfg.lookback_days}d`);
  out.push({ json: { competitor: c.name, source_type: 'news',
    feed_url: `https://news.google.com/rss/search?q=${q}&hl=en-IN&gl=IN&ceid=IN:en` } });
  if (c.blog_rss) out.push({ json: { competitor: c.name, source_type: 'blog', feed_url: c.blog_rss } });
}
return out;

// Keep only recent, valid items and cap items per feed (protects the free LLM quota)
const cfg = $('Config').first().json;
const cutoff = Date.now() - Number(cfg.lookback_days) * 86400000;
const perFeed = {};
const seenTitles = new Set();
const out = [];
for (const { json: j } of $input.all()) {
  if (j.error || !j.link || !j.title) continue;
  const ts = Date.parse(j.isoDate || j.pubDate || '');
  if (!isNaN(ts) && ts < cutoff) continue;
  const titleKey = String(j.title).toLowerCase().replace(/\s+-\s+[^-]+$/, '').trim();
  if (seenTitles.has(titleKey)) continue;           // same story syndicated by several outlets
  seenTitles.add(titleKey);
  const key = `${j.competitor}|${j.source_type}`;
  perFeed[key] = (perFeed[key] || 0) + 1;
  if (perFeed[key] > Number(cfg.max_items_per_feed)) continue;
  out.push({ json: {
    competitor: j.competitor,
    source_type: j.source_type,
    title: j.title,
    link: j.link,
    published: isNaN(ts) ? '' : new Date(ts).toISOString(),
    snippet: String(j.contentSnippet || j.content || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 600),
  } });
}
return out;

